"""Split the line between pt1 and pt2 at position 'where', which
    is an x coordinate if isHorizontal is False, a y coordinate if
    isHorizontal is True. Return a list of two line segments if the
    line was successfully split, or a list containing the original
    line.

        >>> printSegments(splitLine((0, 0), (100, 100), 50, True))
        ((0, 0), (50, 50))
        ((50, 50), (100, 100))
        >>> printSegments(splitLine((0, 0), (100, 100), 100, True))
        ((0, 0), (100, 100))
        >>> printSegments(splitLine((0, 0), (100, 100), 0, True))
        ((0, 0), (0, 0))
        ((0, 0), (100, 100))
        >>> printSegments(splitLine((0, 0), (100, 100), 0, False))
        ((0, 0), (0, 0))
        ((0, 0), (100, 100))
        >>> printSegments(splitLine((100, 0), (0, 0), 50, False))
        ((100, 0), (50, 0))
        ((50, 0), (0, 0))
        >>> printSegments(splitLine((0, 100), (0, 0), 50, True))
        ((0, 100), (0, 50))
        ((0, 50), (0, 0))
    """
def splitLine(pt1: Any, pt2: Any, where: Any, isHorizontal: Any) -> object {
    (pt1x, pt1y) = pt1;
    (pt2x, pt2y) = pt2;
    ax = pt2x - pt1x;
    ay = pt2y - pt1y;
    bx = pt1x;
    `by = pt1y;
    a = (ax, ay)[isHorizontal];
    if (a == 0) {
        return [(pt1, pt2)];
    }
    t = (where - (bx, `by)[isHorizontal]) / a;
    if (0 <= t < 1) {
        midPt = (((ax * t) + bx), ((ay * t) + `by));
        return [(pt1, midPt), (midPt, pt2)];
    } else {
        return [(pt1, pt2)];
    }
}

"""L{import_function} is a shortcut that will import and return L{function}
    if it is a I{str}. If not, then it is assumed that L{function} is callable,
    and is returned."""
def import_function(function: Any) -> object {
    if isinstance(function, str) {
        (m, f) = function.rsplit('.', 1);
        return getattr(__import__(m, {}, {}, ['']), f);
    }
    return function;
}

