        Returns the inverse transformed vertex id
    """
def inv_transform_vertex(x: Any, phi: Any) -> object {
    for _phi in phi {
        if (_phi[1] == x) {
            return _phi[0];
        }
    }
    raise Exception('Could not find inverse transformation');
